import math
import torch
import torch.nn as nn
import torch.nn.init as init
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor conv3d_forward(torch::Tensor x,
                              torch::Tensor w,
                              c10::optional<torch::Tensor> b,
                              int stride, int padding, int dilation, int groups);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
using namespace cute;
// Structural rewrite: CTA-level spatial output tiling with cooperative
// shared-memory staging of the reusable input tile (with halo) in addition
// to caching the full weight tensor. Each thread block loads one input
// sub-volume (covering the receptive field of its output tile) once into
// shared memory and every thread in the block reuses it across all output
// channels, drastically cutting redundant global memory traffic compared
// to the previous one-thread-per-output-position direct kernel.
template <typename T>
__global__ void conv3d_kernel_tiled(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int Cin, int D, int H, int Win,
    int Cout, int K,
    int stride, int padding, int dilation,
    int groups, int Cin_per_group, int Cout_per_group,
    int Do, int Ho, int Wo,
    int numTilesH)
{
  constexpr int REG_W = 4;
  const int n = blockIdx.z;
  const int tw = blockIdx.x;
  const int combined = blockIdx.y;
  const int th = combined % numTilesH;
  const int td = combined / numTilesH;
  const int TILE_W_THREADS = blockDim.x;
  const int TILE_H = blockDim.y;
  const int TILE_D = blockDim.z;
  const int TILE_W = TILE_W_THREADS * REG_W;
  const int od0 = td * TILE_D;
  const int oh0 = th * TILE_H;
  const int ow0 = tw * TILE_W;
  const int ld = threadIdx.z;
  const int lh = threadIdx.y;
  const int lw = threadIdx.x;
  const int od = od0 + ld;
  const int oh = oh0 + lh;
  const int ow_base_local = lw * REG_W;
  int ow_r[REG_W];
  bool validw_r[REG_W];
  #pragma unroll
  for (int r = 0; r < REG_W; ++r) {
    ow_r[r] = ow0 + ow_base_local + r;
    validw_r[r] = ow_r[r] < Wo;
  }
  const bool validdh = (od < Do) && (oh < Ho);
  const int inTileD = (TILE_D - 1) * stride + (K - 1) * dilation + 1;
  const int inTileH = (TILE_H - 1) * stride + (K - 1) * dilation + 1;
  const int inTileW = (TILE_W - 1) * stride + (K - 1) * dilation + 1;
  const int id0 = od0 * stride - padding;
  const int ih0 = oh0 * stride - padding;
  const int iw0 = ow0 * stride - padding;
  const int64_t sXn = (int64_t)Cin * D * H * Win;
  const int64_t sXc = (int64_t)D * H * Win;
  const int64_t sXd = (int64_t)H * Win;
  const int64_t sXh = (int64_t)Win;
  const int64_t sYn = (int64_t)Cout * Do * Ho * Wo;
  const int64_t sYc = (int64_t)Do * Ho * Wo;
  const int64_t sYd = (int64_t)Ho * Wo;
  const int64_t sYh = (int64_t)Wo;
  const T* Xn = X + (int64_t)n * sXn;
  T* Yn = Y + (int64_t)n * sYn;
  const int K3 = K * K * K;
  const int wCstride = Cin_per_group * K3;
  extern __shared__ __align__(16) unsigned char smem_raw[];
  T* smem = reinterpret_cast<T*>(smem_raw);
  const int weight_size = Cout * Cin_per_group * K3;
  T* sW = smem;
  T* sX = smem + weight_size;
  const int blockThreads = blockDim.x * blockDim.y * blockDim.z;
  const int tid = (threadIdx.z * blockDim.y + threadIdx.y) * blockDim.x + threadIdx.x;
  if (sizeof(T) == sizeof(float) && (((uintptr_t)W) % 16 == 0) && (((uintptr_t)sW) % 16 == 0)) {
    const int weight_size4 = weight_size / 4;
    const float4* Wv = reinterpret_cast<const float4*>(W);
    float4* sWv = reinterpret_cast<float4*>(sW);
    for (int idx4 = tid; idx4 < weight_size4; idx4 += blockThreads) {
      sWv[idx4] = Wv[idx4];
    }
    for (int idx = weight_size4 * 4 + tid; idx < weight_size; idx += blockThreads) {
      sW[idx] = W[idx];
    }
  } else {
    for (int idx = tid; idx < weight_size; idx += blockThreads) {
      sW[idx] = W[idx];
    }
  }
  const int inHW = inTileH * inTileW;
  const int inDHW = inTileD * inHW;
  const int inTileSize = Cin * inDHW;
  for (int idx = tid; idx < inTileSize; idx += blockThreads) {
    int c = idx / inDHW;
    int rem = idx - c * inDHW;
    int dloc = rem / inHW;
    rem -= dloc * inHW;
    int hloc = rem / inTileW;
    int wloc = rem - hloc * inTileW;
    int id = id0 + dloc;
    int ih = ih0 + hloc;
    int iw = iw0 + wloc;
    T v = static_cast<T>(0);
    if ((unsigned)id < (unsigned)D && (unsigned)ih < (unsigned)H && (unsigned)iw < (unsigned)Win) {
      v = Xn[c * sXc + (int64_t)id * sXd + (int64_t)ih * sXh + iw];
    }
    sX[idx] = v;
  }
  __syncthreads();
  if (!validdh) return;
  const int d_base = ld * stride;
  const int h_base = lh * stride;
  constexpr int CO_TILE = 8;
  for (int co0 = 0; co0 < Cout; co0 += CO_TILE) {
    const int g = co0 / Cout_per_group;
    const int group_end = (g + 1) * Cout_per_group;
    int tile_count = CO_TILE;
    if (co0 + tile_count > group_end) tile_count = group_end - co0;
    const int ci_base = g * Cin_per_group;
    float acc[REG_W][CO_TILE];
    #pragma unroll
    for (int r = 0; r < REG_W; ++r) {
      #pragma unroll
      for (int t = 0; t < CO_TILE; ++t) {
        if (t < tile_count) {
          const int co = co0 + t;
          acc[r][t] = (B != nullptr) ? (float)B[co] : 0.0f;
        } else {
          acc[r][t] = 0.0f;
        }
      }
    }
    for (int ci = 0; ci < Cin_per_group; ++ci) {
      const int ci_global = ci_base + ci;
      const T* sXc_ptr = sX + (int64_t)ci_global * inDHW;
      for (int kd = 0; kd < K; ++kd) {
        const int dloc = d_base + kd * dilation;
        const T* sXd_ptr = sXc_ptr + (int64_t)dloc * inHW;
        for (int kh = 0; kh < K; ++kh) {
          const int hloc = h_base + kh * dilation;
          const T* sXh_ptr = sXd_ptr + (int64_t)hloc * inTileW;
          for (int kw = 0; kw < K; ++kw) {
            const int wloc_off = kw * dilation;
            float xval[REG_W];
            #pragma unroll
            for (int r = 0; r < REG_W; ++r) {
              const int wloc = ow_base_local * stride + r * stride + wloc_off;
              xval[r] = (float)sXh_ptr[wloc];
            }
            #pragma unroll
            for (int t = 0; t < CO_TILE; ++t) {
              if (t < tile_count) {
                const int co = co0 + t;
                const T* sWptr = sW + (int64_t)co * wCstride + (int64_t)ci * K3 +
                                 (int64_t)kd * K * K + (int64_t)kh * K + kw;
                const float wval = (float)(*sWptr);
                #pragma unroll
                for (int r = 0; r < REG_W; ++r) {
                  acc[r][t] += xval[r] * wval;
                }
              }
            }
          }
        }
      }
    }
    #pragma unroll
    for (int r = 0; r < REG_W; ++r) {
      if (!validw_r[r]) continue;
      #pragma unroll
      for (int t = 0; t < CO_TILE; ++t) {
        if (t < tile_count) {
          const int co = co0 + t;
          Yn[co * sYc + (int64_t)od * sYd + (int64_t)oh * sYh + ow_r[r]] = static_cast<T>(acc[r][t]);
        }
      }
    }
  }
}
torch::Tensor conv3d_forward(torch::Tensor x,
                              torch::Tensor w,
                              c10::optional<torch::Tensor> b,
                              int stride, int padding, int dilation, int groups) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(w.is_cuda(), "w must be CUDA");
  if (b.has_value()) TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA if provided");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  if (b.has_value()) TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");
  TORCH_CHECK(x.dim() == 5, "x must be [N, C, D, H, W]");
  TORCH_CHECK(w.dim() == 5, "w must be [Cout, Cin/groups, K, K, K]");
  int64_t N   = x.size(0);
  int64_t Cin = x.size(1);
  int64_t D   = x.size(2);
  int64_t H   = x.size(3);
  int64_t Win = x.size(4);
  int64_t Cout = w.size(0);
  int64_t Cin_per_group = w.size(1);
  int64_t K = w.size(2);
  TORCH_CHECK(w.size(3) == K && w.size(4) == K, "kernel must be cubic");
  TORCH_CHECK(Cin % groups == 0, "Cin must be divisible by groups");
  TORCH_CHECK(Cout % groups == 0, "Cout must be divisible by groups");
  TORCH_CHECK(Cin / groups == Cin_per_group, "weight Cin/groups mismatch");
  int64_t Cout_per_group = Cout / groups;
  TORCH_CHECK(stride > 0 && dilation > 0, "stride and dilation must be > 0");
  TORCH_CHECK(padding >= 0, "padding must be >= 0");
  int64_t Do = (D + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
  int64_t Ho = (H + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
  int64_t Wo = (Win + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
  TORCH_CHECK(Do > 0 && Ho > 0 && Wo > 0, "Invalid output size computed");
  auto x_c = x.contiguous();
  auto w_c = w.contiguous();
  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == Cout, "bias must be [Cout]");
    b_ptr = b_c.data_ptr<float>();
  }
  auto y = torch::empty({N, Cout, Do, Ho, Wo}, x.options());
  constexpr int TILE_W = 16;
  constexpr int TILE_H = 8;
  constexpr int TILE_D = 4;
  constexpr int REG_W = 4;
  const int numTilesW = (int)((Wo + TILE_W - 1) / TILE_W);
  const int numTilesH = (int)((Ho + TILE_H - 1) / TILE_H);
  const int numTilesD = (int)((Do + TILE_D - 1) / TILE_D);
  dim3 block(TILE_W / REG_W, TILE_H, TILE_D);
  dim3 grid(
      (unsigned)numTilesW,
      (unsigned)(numTilesH * numTilesD),
      (unsigned)N
  );
  const int inTileD = (TILE_D - 1) * stride + (int)(K - 1) * dilation + 1;
  const int inTileH = (TILE_H - 1) * stride + (int)(K - 1) * dilation + 1;
  const int inTileW = (TILE_W - 1) * stride + (int)(K - 1) * dilation + 1;
  size_t weight_bytes = (size_t)Cout * Cin_per_group * K * K * K * sizeof(float);
  size_t input_tile_bytes = (size_t)Cin * inTileD * inTileH * inTileW * sizeof(float);
  size_t smem_bytes = weight_bytes + input_tile_bytes;
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  if (smem_bytes > 48 * 1024) {
    cudaFuncSetAttribute(conv3d_kernel_tiled<float>,
                          cudaFuncAttributeMaxDynamicSharedMemorySize,
                          (int)smem_bytes);
  }
  conv3d_kernel_tiled<float><<<grid, block, smem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)Cin, (int)D, (int)H, (int)Win,
      (int)Cout, (int)K,
      (int)stride, (int)padding, (int)dilation,
      (int)groups, (int)Cin_per_group, (int)Cout_per_group,
      (int)Do, (int)Ho, (int)Wo,
      numTilesH
  );
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv3d_kernel_tiled launch failed: ", cudaGetErrorString(err));
  return y;
}
"""

conv3d_ext = load_inline(
    name="cute_conv3d_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["conv3d_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include",
                          "/root/cutegen_test/cutegen/cutlass/include/cute/"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Standard 3D convolution (square kernel) implemented with a single custom
    CUDA kernel built using CuTe tensors/layouts. The kernel caches the full
    weight tensor for a (n, out-channel-group) block in shared memory and
    cooperatively computes a tile of output spatial positions across threads.
    """
    def __init__(self,
                 in_channels: int,
                 out_channels: int,
                 kernel_size: int,
                 stride: int = 1,
                 padding: int = 0,
                 dilation: int = 1,
                 groups: int = 1,
                 bias: bool = False) -> None:
        super().__init__()

        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = int(kernel_size)
        self.stride = int(stride)
        self.padding = int(padding)
        self.dilation = int(dilation)
        self.groups = int(groups)

        assert self.in_channels % self.groups == 0
        assert self.out_channels % self.groups == 0

        Cin_per_group = self.in_channels // self.groups
        K = self.kernel_size

        self.weight = nn.Parameter(torch.empty(self.out_channels, Cin_per_group, K, K, K))
        if bias:
            self.bias = nn.Parameter(torch.empty(self.out_channels))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()
        self._ext = conv3d_ext

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = self.weight.size(1) * self.weight.size(2) * self.weight.size(3) * self.weight.size(4)
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.conv3d_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias if self.bias is not None else None,
            int(self.stride),
            int(self.padding),
            int(self.dilation),
            int(self.groups),
        )

