"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
using namespace cute;
// Structural rewrite: CTA-level spatial output tiling with cooperative
// shared-memory staging of the reusable input tile (with halo) in addition
// to caching the full weight tensor. Each thread block loads one input
// sub-volume (covering the receptive field of its output tile) once into
// shared memory and every thread in the block reuses it across all output
// channels, drastically cutting redundant global memory traffic compared
// to the previous one-thread-per-output-position direct kernel.
template <typename T>
__global__ void conv3d_kernel_tiled(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int Cin, int D, int H, int Win,
    int Cout, int K,
    int stride, int padding, int dilation,
    int groups, int Cin_per_group, int Cout_per_group,
    int Do, int Ho, int Wo,
    int numTilesH)
{
  constexpr int REG_W = 2;
  const int n = blockIdx.z;
  const int tw = blockIdx.x;
  const int combined = blockIdx.y;
  const int th = combined % numTilesH;
  const int td = combined / numTilesH;
  const int TILE_W_THREADS = blockDim.x;
  const int TILE_H = blockDim.y;
  const int TILE_D = blockDim.z;
  const int TILE_W = TILE_W_THREADS * REG_W;
  const int od0 = td * TILE_D;
  const int oh0 = th * TILE_H;
  const int ow0 = tw * TILE_W;
  const int ld = threadIdx.z;
  const int lh = threadIdx.y;
  const int lw = threadIdx.x;
  const int od = od0 + ld;
  const int oh = oh0 + lh;
  const int ow_base_local = lw * REG_W;
  int ow_r[REG_W];
  bool validw_r[REG_W];
  #pragma unroll
  for (int r = 0; r < REG_W; ++r) {
    ow_r[r] = ow0 + ow_base_local + r;
    validw_r[r] = ow_r[r] < Wo;
  }
  const bool validdh = (od < Do) && (oh < Ho);
  const int inTileD = (TILE_D - 1) * stride + (K - 1) * dilation + 1;
  const int inTileH = (TILE_H - 1) * stride + (K - 1) * dilation + 1;
  const int inTileW = (TILE_W - 1) * stride + (K - 1) * dilation + 1;
  const int id0 = od0 * stride - padding;
  const int ih0 = oh0 * stride - padding;
  const int iw0 = ow0 * stride - padding;
  const int64_t sXn = (int64_t)Cin * D * H * Win;
  const int64_t sXc = (int64_t)D * H * Win;
  const int64_t sXd = (int64_t)H * Win;
  const int64_t sXh = (int64_t)Win;
  const int64_t sYn = (int64_t)Cout * Do * Ho * Wo;
  const int64_t sYc = (int64_t)Do * Ho * Wo;
  const int64_t sYd = (int64_t)Ho * Wo;
  const int64_t sYh = (int64_t)Wo;
  const T* Xn = X + (int64_t)n * sXn;
  T* Yn = Y + (int64_t)n * sYn;
  const int K3 = K * K * K;
  const int wCstride = Cin_per_group * K3;
  extern __shared__ __align__(16) unsigned char smem_raw[];
  T* smem = reinterpret_cast<T*>(smem_raw);
  const int weight_size = Cout * Cin_per_group * K3;
  T* sW = smem;
  T* sX = smem + weight_size;
  const int blockThreads = blockDim.x * blockDim.y * blockDim.z;
  const int tid = (threadIdx.z * blockDim.y + threadIdx.y) * blockDim.x + threadIdx.x;
  if (sizeof(T) == sizeof(float) && (((uintptr_t)W) % 16 == 0) && (((uintptr_t)sW) % 16 == 0)) {
    const int weight_size4 = weight_size / 4;
    const float4* Wv = reinterpret_cast<const float4*>(W);
    float4* sWv = reinterpret_cast<float4*>(sW);
    for (int idx4 = tid; idx4 < weight_size4; idx4 += blockThreads) {
      sWv[idx4] = Wv[idx4];
    }
    for (int idx = weight_size4 * 4 + tid; idx < weight_size; idx += blockThreads) {
      sW[idx] = W[idx];
    }
  } else {
    for (int idx = tid; idx < weight_size; idx += blockThreads) {
      sW[idx] = W[idx];
    }
  }
  const int inHW = inTileH * inTileW;
  const int inDHW = inTileD * inHW;
  const int inTileSize = Cin * inDHW;
  for (int idx = tid; idx < inTileSize; idx += blockThreads) {
    int c = idx / inDHW;
    int rem = idx - c * inDHW;
    int dloc = rem / inHW;
    rem -= dloc * inHW;
    int hloc = rem / inTileW;
    int wloc = rem - hloc * inTileW;
    int id = id0 + dloc;
    int ih = ih0 + hloc;
    int iw = iw0 + wloc;
    T v = static_cast<T>(0);
    if ((unsigned)id < (unsigned)D && (unsigned)ih < (unsigned)H && (unsigned)iw < (unsigned)Win) {
      v = Xn[c * sXc + (int64_t)id * sXd + (int64_t)ih * sXh + iw];
    }
    sX[idx] = v;
  }
  __syncthreads();
  if (!validdh) return;
  const int d_base = ld * stride;
  const int h_base = lh * stride;
  constexpr int CO_TILE = 8;
  for (int co0 = 0; co0 < Cout; co0 += CO_TILE) {
    const int g = co0 / Cout_per_group;
    const int group_end = (g + 1) * Cout_per_group;
    int tile_count = CO_TILE;
    if (co0 + tile_count > group_end) tile_count = group_end - co0;
    const int ci_base = g * Cin_per_group;
    float acc[REG_W][CO_TILE];
    #pragma unroll
    for (int r = 0; r < REG_W; ++r) {
      #pragma unroll
      for (int t = 0; t < CO_TILE; ++t) {
        if (t < tile_count) {
          const int co = co0 + t;
          acc[r][t] = (B != nullptr) ? (float)B[co] : 0.0f;
        } else {
          acc[r][t] = 0.0f;
        }
      }
    }
    for (int ci = 0; ci < Cin_per_group; ++ci) {
      const int ci_global = ci_base + ci;
      const T* sXc_ptr = sX + (int64_t)ci_global * inDHW;
      for (int kd = 0; kd < K; ++kd) {
        const int dloc = d_base + kd * dilation;
        const T* sXd_ptr = sXc_ptr + (int64_t)dloc * inHW;
        for (int kh = 0; kh < K; ++kh) {
          const int hloc = h_base + kh * dilation;
          const T* sXh_ptr = sXd_ptr + (int64_t)hloc * inTileW;
          for (int kw = 0; kw < K; ++kw) {
            const int wloc_off = kw * dilation;
            float xval[REG_W];
            #pragma unroll
            for (int r = 0; r < REG_W; ++r) {
              const int wloc = ow_base_local * stride + r * stride + wloc_off;
              xval[r] = (float)sXh_ptr[wloc];
            }
            #pragma unroll
            for (int t = 0; t < CO_TILE; ++t) {
              if (t < tile_count) {
                const int co = co0 + t;
                const T* sWptr = sW + (int64_t)co * wCstride + (int64_t)ci * K3 +
                                 (int64_t)kd * K * K + (int64_t)kh * K + kw;
                const float wval = (float)(*sWptr);
